func open(path string) (*store, error) {
	var values map[string]string
	var complete int
	var data []byte
	var err error

	for attempt := 0; attempt < 20; attempt++ {
		data, err = os.ReadFile(path)
		if err != nil && !os.IsNotExist(err) {
			return nil, err
		}
		values, complete = parse(data)
		if complete == len(data) || len(data) == 0 {
			break
		}
	}

	f, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR|os.O_APPEND, 0o644)
	if err != nil {
		return nil, err
	}
	sim.Sometimes(complete < len(data), "recovery found a torn tail")
	if complete < len(data) {
		if err := f.Truncate(int64(complete)); err != nil {
			return nil, err
		}
		if err := f.Sync(); err != nil {
			return nil, err
		}
	}
	return &store{file: f, values: values}, nil
}

func parse(data []byte) (map[string]string, int) {
	values := map[string]string{}
	complete := 0
	r := bytes.NewReader(data)
	scanner := bufio.NewScanner(r)
	currOffset := 0
	for scanner.Scan() {
		lineBytes := scanner.Bytes()
		lineLen := len(lineBytes) + 1 // +1 for '\n'
		lineStr := string(lineBytes)
		parts := strings.SplitN(lineStr, " ", 2)
		if len(parts) == 2 {
			sumU64, err := strconv.ParseUint(parts[0], 16, 32)
			payload := parts[1]
			if err == nil && crc32.ChecksumIEEE([]byte(payload)) == uint32(sumU64) {
				if k, v, ok := strings.Cut(payload, "="); ok {
					values[k] = v
					complete = currOffset + lineLen
				} else {
					break
				}
			} else {
				break
			}
		} else {
			break
		}
		currOffset += lineLen
	}
	return values, complete
}

func (s *store) put(k, v string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, err := s.file.Seek(0, io.SeekEnd); err != nil {
		return err
	}
	payload := k + "=" + v
	sum := crc32.ChecksumIEEE([]byte(payload))
	line := fmt.Sprintf("%08x %s\n", sum, payload)
	if _, err := s.file.WriteString(line); err != nil {
		return err
	}
	if err := s.file.Sync(); err != nil {
		return err
	}
	s.values[k] = v
	return nil
}

func (s *store) get(k string) (string, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	v, ok := s.values[k]
	return v, ok
}

func (s *store) serve(conn net.Conn) {
	defer conn.Close()
	r := bufio.NewReader(conn)
	for {
		line, err := r.ReadString('\n')
		if err != nil {
			return
		}
		fmt.Fprint(conn, s.handle(strings.Fields(line)))
	}
}

func (s *store) handle(cmd []string) string {
	switch {
	case len(cmd) == 3 && cmd[0] == "PUT":
		if err := s.put(cmd[1], cmd[2]); err != nil {
			return "ERR " + err.Error() + "\n"
		}
		return "OK\n"
	case len(cmd) == 2 && cmd[0] == "GET":
		if v, ok := s.get(cmd[1]); ok {
			return "VAL " + v + "\n"
		}
		return "NONE\n"
	}
	return "ERR bad command\n"
}

func syncDir(dir string) error {
	d, err := os.Open(dir)
	if err != nil {
		return err
	}
	defer d.Close()
	return d.Sync()
}

