		if err := syncDir(d); err != nil {
			log.Fatal(err)
		}
	}
	ln, err := sim.Listen("tcp", *addr)
	if err != nil {
		log.Fatal(err)
	}
	fmt.Printf("serving %d keys on %s\n", len(s.values), *addr)
	for {
		conn, err := ln.Accept()
		if err != nil {
			log.Fatal(err)
		}
		go s.serve(conn)
	}
}

func open(path string) (*store, error) {
	f, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR|os.O_APPEND, 0o644)
	if err != nil {
		return nil, err
	}

	info, err := f.Stat()
	if err != nil {
		f.Close()
		return nil, err
	}
	fileSize := info.Size()

	var data []byte
	if fileSize > 0 {
		data = make([]byte, fileSize)
		_, _ = f.ReadAt(data, 0)
	}

	values, complete := parseAndRecover(f, data, fileSize)

	sim.Sometimes(int64(complete) < fileSize, "recovery found a torn tail")
	if int64(complete) < fileSize {
		if err := f.Truncate(int64(complete)); err != nil {
			f.Close()
			return nil, err
		}
		if err := f.Sync(); err != nil {
			f.Close()
			return nil, err
		}
	}
